// Some portions generated by Claude

// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId,
	waitForRoute
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-shell');
const OTHER_ID = uniqueRepositoryId('workbench-shell-other');

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID, { graphs: ['bsbm', 'spl'] });
	await createSeededRepository(request, serverBaseUrl(), OTHER_ID, { graphs: [] });
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
	await deleteRepository(request, serverBaseUrl(), OTHER_ID);
});

async function openRepositorySwitcher(page) {
	await page.locator('#workbench-repository-switcher').click();
	await expect(page.locator('#workbench-repository-popover')).toBeVisible();
	await expect(page.locator(`#workbench-repository-options a[data-repository-id="${REPOSITORY_ID}"]`))
		.toBeVisible();
}

test('on a desktop the context block tops the sidebar and names the server and repository', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'), { waitUntil: 'networkidle' });
	const bar = page.locator('#workbench-contextbar');
	await expect(bar).toBeVisible();
	const box = await bar.boundingBox();
	const menu = await page.locator('#navigation').boundingBox();
	expect(Math.abs(box.x - menu.x), 'the context block sits in the sidebar column').toBeLessThanOrEqual(1);
	expect(box.y + box.height, 'the menu follows the context block').toBeLessThanOrEqual(menu.y + 1);
	await expect(bar.locator('#workbench-repository-switcher')).toContainText(REPOSITORY_ID);
});

test('the repository panel, not a switcher of its own, names the server and the user', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'), { waitUntil: 'networkidle' });
	const bar = page.locator('#workbench-contextbar');
	await expect(bar.locator('.workbench-switcher__button')).toHaveCount(1);
	await expect(bar.locator('#workbench-server-switcher')).toHaveCount(0);
	await expect(bar.locator('#workbench-user-switcher')).toHaveCount(0);
	await bar.locator('#workbench-repository-switcher').click();
	const popover = page.locator('#workbench-repository-popover');
	await expect(popover).toBeVisible();
	await expect(popover.locator('.workbench-popover__server')).toContainText(new URL(serverBaseUrl()).host);
	await expect(popover.locator('.workbench-popover__server')).toContainText('Not signed in');
});

test('the repository switcher filters and chooses repositories', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl('NONE', 'repositories'), { waitUntil: 'networkidle' });
	await openRepositorySwitcher(page);
	await expect(page.locator(`#workbench-repository-options a[data-repository-id="${OTHER_ID}"]`)).toBeVisible();
	await page.locator('#workbench-repository-filter').fill(REPOSITORY_ID.slice(0, 'workbench-shell-'.length + 4));
	await expect(page.locator(`#workbench-repository-options a[data-repository-id="${REPOSITORY_ID}"]`)).toBeVisible();
	await expect(page.locator(`#workbench-repository-options a[data-repository-id="${OTHER_ID}"]`)).toBeHidden();
	await page.locator(`#workbench-repository-options a[data-repository-id="${REPOSITORY_ID}"]`).click();
	await expect(page).toHaveURL(new RegExp(`/repositories/${REPOSITORY_ID}/summary$`));

	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'networkidle' });
	await openRepositorySwitcher(page);
	await page.locator(`#workbench-repository-options a[data-repository-id="${OTHER_ID}"]`).click();
	await expect(page).toHaveURL(new RegExp(`/repositories/${OTHER_ID}/query$`));
});

test('the repository switcher works with the keyboard only', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'types'), { waitUntil: 'networkidle' });
	const button = page.locator('#workbench-repository-switcher');
	await button.focus();
	await page.keyboard.press('Enter');
	await expect(page.locator('#workbench-repository-filter')).toBeFocused();
	await expect(page.locator(`#workbench-repository-options a[data-repository-id="${OTHER_ID}"]`)).toBeVisible();
	await page.keyboard.press('Escape');
	await expect(page.locator('#workbench-repository-popover')).toBeHidden();
	await expect(button).toBeFocused();
	await expect(button).toHaveAttribute('aria-expanded', 'false');

	await page.keyboard.press('ArrowDown');
	await expect(page.locator('#workbench-repository-filter')).toBeFocused();
	await page.keyboard.type(OTHER_ID);
	await page.keyboard.press('ArrowDown');
	await expect(page.locator(`#workbench-repository-options a[data-repository-id="${OTHER_ID}"]`)).toBeFocused();
	await page.keyboard.press('Enter');
	await expect(page).toHaveURL(new RegExp(`/repositories/${OTHER_ID}/types$`));
});

test('the menu stays in view while a long page scrolls', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'types'), { waitUntil: 'networkidle' });
	await expect(page.locator('#types-results tbody tr').nth(5)).toBeAttached();
	await page.waitForFunction(() => {
		window.scrollTo(0, document.documentElement.scrollHeight);
		return window.scrollY > 600;
	});
	const query = page.locator('#navigation a[data-workbench-nav-href$="/query"], #navigation a[data-workbench-nav-href="query"]').first();
	const box = await query.boundingBox();
	expect(box, 'the Query menu link is rendered').not.toBeNull();
	expect(box.y).toBeGreaterThanOrEqual(0);
	expect(box.y + box.height).toBeLessThanOrEqual(900);
});

// Plan task M13.1 (user request): the menu rests where it sticks, so it does not move when the page starts to scroll.
test('the menu does not move when the page starts to scroll', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'types'), { waitUntil: 'networkidle' });
	await expect(page.locator('#types-results tbody tr').nth(5)).toBeAttached();
	const menu = page.locator('#workbench-navigation-disclosure');
	const top = async (scrollY) => {
		await page.evaluate((y) => window.scrollTo(0, y), scrollY);
		await expect.poll(() => page.evaluate(() => window.scrollY)).toBe(scrollY);
		return (await menu.boundingBox()).y;
	};
	const resting = await top(0);
	for (const scrollY of [50, 200, 1000]) {
		expect(Math.abs((await top(scrollY)) - resting), `menu top after scrolling ${scrollY}px`).toBeLessThanOrEqual(1);
	}
	const bar = await page.locator('#workbench-contextbar').boundingBox();
	const first = await page.locator('#navigation a').first().boundingBox();
	expect(first.y, 'the first menu link is below the context bar').toBeGreaterThanOrEqual(bar.y + bar.height);
	expect(first.y + first.height).toBeLessThanOrEqual(900);
});

// Plan task M13.3 (user request): Summary shows the repository at once and counts it afterwards, for up to two seconds.
test('Summary shows the repository before its counts arrive', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	let release;
	const held = new Promise((resolve) => { release = resolve; });
	const countRequests = [];
	await page.route((url) => url.pathname.endsWith('/summary') && url.searchParams.get('counts') === 'true', async (route) => {
		countRequests.push(route.request().url());
		await held;
		await route.continue();
	});
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'summary');
	const value = (label) => page.locator('#workbench-summary .workbench-kv__row').filter({
		has: page.locator('dt', { hasText: new RegExp(`^${label}$`) })
	}).locator('dd');
	await expect(value('ID')).toHaveText(REPOSITORY_ID);
	await expect(value('Statements')).toHaveText('Counting…');
	await expect(value('Named graphs')).toHaveText('Counting…');
	expect(countRequests).toHaveLength(1);

	release();
	await expect(value('Statements')).toHaveText(/^[\d,]+$/);
	await expect(value('Named graphs')).toHaveText('2');
});

test('menu groups are labeled the same way, with Query first', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'), { waitUntil: 'networkidle' });
	const groups = await page.locator('#navigation .workbench-nav-group').evaluateAll(elements => elements.map(group => ({
		label: group.querySelector('.workbench-nav-group__label').textContent.trim(),
		disclosure: Boolean(group.querySelector('details')),
		items: Array.from(group.querySelectorAll('a, span.disabled')).map(item => item.textContent.trim())
	})));
	expect(groups.map(group => group.label)).toEqual(['Repository', 'Data', 'Server', 'System']);
	expect(groups.every(group => !group.disclosure)).toBe(true);
	expect(groups[0].items[0]).toBe('Query');
	expect(groups[0].items).toContain('Graphs');
	expect(groups[3].items).toEqual(['Information']);
});

test('dark mode shows the light-ink logo without a white plate', async ({ browser }) => {
	const context = await browser.newContext({ colorScheme: 'dark', viewport: { width: 1440, height: 900 } });
	const page = await context.newPage();
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'), { waitUntil: 'networkidle' });
	const brand = await page.locator('#logo').evaluate((element) => {
		const visible = Array.from(element.querySelectorAll('img')).filter((image) => image.getClientRects().length > 0);
		return {
			sources: visible.map((image) => image.getAttribute('src')),
			background: getComputedStyle(element).backgroundColor
		};
	});
	await context.close();
	expect(brand.sources.some((source) => source.endsWith('/images/logo-dark.png')), JSON.stringify(brand)).toBe(true);
	expect(brand.sources.every((source) => source.endsWith('-dark.png')), JSON.stringify(brand)).toBe(true);
	expect(brand.background).toBe('rgba(0, 0, 0, 0)');
});

